package com.simpletoob.app;

import org.json.*;
import java.util.*;

/** Visible YouTube Home cards in server order. No ad/Shorts/menu/hover-preview traversal. */
final class HomeFeedParser {
    static final class Result {
        final List<Video> videos;final String next,notice;final boolean recognized,signedOut;
        Result(List<Video> videos,String next,String notice,boolean recognized,boolean signedOut){this.videos=videos;this.next=next;this.notice=notice;this.recognized=recognized;this.signedOut=signedOut;}
    }
    private final List<Video> videos=new ArrayList<>();private final Set<String> seen=new HashSet<>();
    private String next="",notice="";private int nodes;private boolean recognized;
    private static final Set<String> SKIP=new HashSet<>(Arrays.asList("adSlotRenderer","inFeedAdLayoutRenderer","displayAdRenderer","promotedVideoRenderer","promotedSparklesWebRenderer","promotedSparklesTextSearchRenderer","adPlacementRenderer","adPlacements","playerAds","ads","reelShelfRenderer","reelItemRenderer","shortsLockupViewModel","shortsLockupViewModelV2","shortsShelfRenderer","menu","navigationEndpoint","onTap","onVisibleCommands","onResponseReceivedCommands","header","masthead","guide","trackingParams","accessibility","engagementPanels"));
    private static final Set<String> BLOCK=new HashSet<>(Arrays.asList("adSlotRenderer","inFeedAdLayoutRenderer","displayAdRenderer","promotedVideoRenderer","promotedSparklesWebRenderer","promotedSparklesTextSearchRenderer","adPlacementRenderer","reelShelfRenderer","reelItemRenderer","shortsLockupViewModel","shortsLockupViewModelV2","shortsShelfRenderer"));
    static Result parse(JSONObject response){HomeFeedParser parser=new HomeFeedParser();Object contents=response.opt("contents");if(contents!=null){Object selected=selected(contents);parser.walk(selected,true,0);}
        for(String key:new String[]{"onResponseReceivedActions","onResponseReceivedEndpoints","onResponseReceivedCommands"}){JSONArray actions=response.optJSONArray(key);if(actions!=null)for(int i=0;i<actions.length();i++){JSONObject action=actions.optJSONObject(i);if(action==null)continue;for(String command:new String[]{"appendContinuationItemsAction","reloadContinuationItemsCommand"}){JSONObject append=action.optJSONObject(command);if(append!=null&&append.has("continuationItems")){String target=append.optString("targetId");if(!target.isEmpty()&&!target.startsWith("browse-feed")&&!target.equals("rich-grid-feed"))continue;parser.recognized=true;parser.walk(append.opt("continuationItems"),true,0);}}}}
        JSONObject continuation=response.optJSONObject("continuationContents");if(continuation!=null)for(String key:new String[]{"richGridContinuation","sectionListContinuation","gridContinuation"}){JSONObject grid=continuation.optJSONObject(key);if(grid!=null){parser.recognized=true;parser.walk(grid,true,0);}}
        JSONObject context=response.optJSONObject("responseContext"),web=context==null?null:context.optJSONObject("mainAppWebResponseContext");return new Result(Collections.unmodifiableList(parser.videos),parser.next,parser.notice,parser.recognized,web!=null&&web.optBoolean("loggedOut"));
    }
    private static Object selected(Object contents){if(contents instanceof JSONObject){JSONObject root=(JSONObject)contents;for(String key:new String[]{"twoColumnBrowseResultsRenderer","singleColumnBrowseResultsRenderer"}){JSONObject browse=root.optJSONObject(key);if(browse==null)continue;JSONArray tabs=browse.optJSONArray("tabs");if(tabs==null)return root;for(int i=0;i<tabs.length();i++){JSONObject wrapper=tabs.optJSONObject(i),tab=wrapper==null?null:wrapper.optJSONObject("tabRenderer");if(tab!=null&&tab.optBoolean("selected"))return tab.opt("content");}return new JSONObject();}}return contents;}
    private void walk(Object value,boolean pagination,int depth){if(value==null||depth>60||++nodes>20000)return;
        if(value instanceof JSONArray){JSONArray array=(JSONArray)value;for(int i=0;i<array.length();i++)walk(array.opt(i),pagination,depth+1);return;}
        if(!(value instanceof JSONObject))return;JSONObject node=(JSONObject)value;
        for(String key:BLOCK)if(node.has(key))return;
        if(node.optBoolean("isAd")||node.has("adBadgeRenderer")||node.has("adMetadata"))return;
        JSONObject grid=node.optJSONObject("richGridRenderer");if(grid!=null){recognized=true;walk(grid.opt("contents"),true,depth+1);return;}
        for(String container:new String[]{"sectionListRenderer","gridRenderer"}){JSONObject list=node.optJSONObject(container);if(list!=null){recognized=true;walk(list.opt(container.equals("gridRenderer")?"items":"contents"),pagination,depth+1);return;}}
        for(String renderer:new String[]{"videoRenderer","compactVideoRenderer","gridVideoRenderer","videoWithContextRenderer"}){JSONObject card=node.optJSONObject(renderer);if(card!=null){addClassic(card);return;}}
        JSONObject lockup=node.optJSONObject("lockupViewModel");if(lockup!=null){addLockup(lockup);return;}
        JSONObject item=node.optJSONObject("continuationItemRenderer");if(item!=null){if(pagination){String token=token(item);if(!token.isEmpty()&&token.length()<=32768)next=token;}return;}
        JSONObject message=node.optJSONObject("messageRenderer");if(message!=null){recognized=true;if(notice.isEmpty())notice=limit(WebJson.text(message.opt("text")),1000);return;}
        if(pagination){JSONArray continuations=node.optJSONArray("continuations");if(continuations!=null)for(int i=0;i<continuations.length();i++){JSONObject entry=continuations.optJSONObject(i),data=entry==null?null:entry.optJSONObject("nextContinuationData");if(data!=null){String token=data.optString("continuation");if(!token.isEmpty()&&token.length()<=32768)next=token;}}}
        Iterator<String> keys=node.keys();while(keys.hasNext()){String key=keys.next();if(SKIP.contains(key)||key.equals("continuations"))continue;boolean nestedPagination=pagination&&!key.toLowerCase(Locale.ROOT).contains("shelf")&&!key.equals("horizontalListRenderer");walk(node.opt(key),nestedPagination,depth+1);}
    }
    private static String token(JSONObject item){for(String endpoint:new String[]{"continuationEndpoint","serviceEndpoint"}){JSONObject ep=item.optJSONObject(endpoint);if(ep==null)continue;JSONObject c=ep.optJSONObject("continuationCommand");if(c!=null)return c.optString("token");JSONObject commands=ep.optJSONObject("commandExecutorCommand");JSONArray list=commands==null?null:commands.optJSONArray("commands");if(list!=null)for(int i=0;i<list.length();i++){JSONObject command=list.optJSONObject(i),continuation=command==null?null:command.optJSONObject("continuationCommand");if(continuation!=null)return continuation.optString("token");}}return "";}
    private void addClassic(JSONObject card){String id=card.optString("videoId");if(!VideoIds.valid(id)||advert(card,0))return;String title=WebJson.text(card.opt("title"));if(title.isEmpty())return;
        Object byline=card.opt("shortBylineText");if(byline==null)byline=card.opt("ownerText");if(byline==null)byline=card.opt("longBylineText");String channel=WebJson.text(byline),url=channel(byline);
        String avatar="";JSONObject supported=card.optJSONObject("channelThumbnailSupportedRenderers"),renderer=supported==null?null:supported.optJSONObject("channelThumbnailWithLinkRenderer");if(renderer!=null)avatar=AccountCollections.thumbnail(renderer.opt("thumbnail"));
        add(VideoMetadata.classic(new Video(id,title,channel,url,AccountCollections.thumbnail(card.opt("thumbnail")),"",WebJson.text(card.opt("publishedTimeText")),duration(WebJson.text(card.opt("lengthText")))).withAvatar(avatar),card));
    }
    private void addLockup(JSONObject card){if(!"LOCKUP_CONTENT_TYPE_VIDEO".equals(card.optString("contentType"))||advert(card,0))return;String id=card.optString("contentId");if(!VideoIds.valid(id))return;JSONObject metadata=card.optJSONObject("metadata"),lockup=metadata==null?null:metadata.optJSONObject("lockupMetadataViewModel");if(lockup==null)return;String title=WebJson.text(lockup.opt("title"));if(title.isEmpty())return;
        String channel="",url=channel(lockup);JSONObject rows=lockup.optJSONObject("metadata");if(rows!=null&&rows.optJSONObject("contentMetadataViewModel")!=null)rows=rows.optJSONObject("contentMetadataViewModel");JSONArray rowList=rows==null?null:rows.optJSONArray("metadataRows");if(rowList!=null&&rowList.length()>0){JSONObject row=rowList.optJSONObject(0);JSONArray parts= row==null?null:row.optJSONArray("metadataParts");if(parts!=null&&parts.length()>0){JSONObject part=parts.optJSONObject(0);if(part!=null)channel=WebJson.text(part.opt("text"));}}
        String thumbnail=AccountCollections.thumbnail(card.opt("contentImage"));long length=0;for(JSONObject overlay:WebJson.objects(card,"thumbnailBadgeViewModel")){length=duration(WebJson.text(overlay.opt("text")));if(length>0)break;}
        String avatar="";JSONObject image=lockup.optJSONObject("image"),decorated=image==null?null:image.optJSONObject("decoratedAvatarViewModel"),wrapper=decorated==null?null:decorated.optJSONObject("avatar"),view=wrapper==null?null:wrapper.optJSONObject("avatarViewModel");if(view!=null)avatar=AccountCollections.thumbnail(view.opt("image"));
        add(VideoMetadata.lockup(new Video(id,title,channel,url,thumbnail,"","",length).withAvatar(avatar),lockup));
    }
    private static boolean advert(Object value,int depth){if(depth>12)return false;if(value instanceof JSONArray){JSONArray rows=(JSONArray)value;for(int i=0;i<Math.min(rows.length(),100);i++)if(advert(rows.opt(i),depth+1))return true;}else if(value instanceof JSONObject){JSONObject object=(JSONObject)value;if(object.optBoolean("isAd")||object.has("adMetadata")||object.has("adSlotMetadata")||object.has("adBadgeRenderer")||object.has("adBadgeViewModel")||object.has("adInfoRenderer"))return true;Iterator<String> keys=object.keys();while(keys.hasNext())if(advert(object.opt(keys.next()),depth+1))return true;}return false;}
    private void add(Video video){if(videos.size()<500&&seen.add(video.id))videos.add(video);}
    private static String channel(Object metadata){for(JSONObject endpoint:WebJson.objects(metadata,"browseEndpoint")){String url=ChannelUrls.parse(endpoint.optString("browseId"));if(url==null)url=ChannelUrls.parse("https://www.youtube.com"+endpoint.optString("canonicalBaseUrl"));if(url!=null)return url;}return "";}
    static long duration(String text){String[] pieces=text.replace("\u200e","").replace("\u200f","").split(":");if(pieces.length<2||pieces.length>3)return 0;long seconds=0;for(int i=0;i<pieces.length;i++){String p=pieces[i].trim();if(!p.matches("[0-9]{1,3}"))return 0;int n=Integer.parseInt(p);if(i>0&&n>=60)return 0;seconds=seconds*60+n;}return seconds;}
    private static String limit(String value,int count){return value.length()<=count?value:value.substring(0,count);}
}
